# Mapping from observed heights: 2->4, 8->3. Verify on all demos.
def f(g, hmap={2:4, 8:3}):
    out=[row[:] for row in g]
    H,W=len(g),len(g[0])
    nz=[(r,c,g[r][c]) for r in range(H) for c in range(W) if g[r][c]!=0]
    rows_nz={r for r,c,v in nz}
    for r,c,v in nz:
        if c not in set() or True:
            pass
    # seed row: the nonzero row(s); use max
    sr=max(rows_nz)
    for c,v in [(c,g[sr][c]) for c in range(W) if g[sr][c]!=0]:
        k=hmap[v]
        for i in range(1,k+1):
            if sr-i>=0:
                out[sr-i][c]=1 if i>1 else v
    return out

